using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class VerifyWallPilot {
static string R=>Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/WallTexturing_20261103"));static string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};static object CR(Collider c)=>new{path=P(c.transform),type=c.GetType().Name,position=V(c.transform.position),rotation=V(c.transform.eulerAngles),scale=V(c.transform.lossyScale),enabled=c.enabled,trigger=c.isTrigger,boundsCenter=V(c.bounds.center),boundsSize=V(c.bounds.size)};
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var s=SceneManager.GetActiveScene();if(s.isDirty){if(s.GetRootGameObjects().Any(g=>g.name=="TemporaryWallReviewCamera"))throw new Exception("Temporary camera remains");if(!EditorSceneManager.SaveScene(s))throw new Exception("Could not save restored material state");}s=EditorSceneManager.OpenScene(s.path,OpenSceneMode.Single);var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var cfg=JObject.Parse(File.ReadAllText(R+"/application_facts.json"));var rr=((JArray)cfg["walls"]).Select(a=>all.First(t=>P(t)==(string)a["path"]).GetComponent<MeshRenderer>()).ToArray();var mat=rr[0].sharedMaterial;bool shared=rr.All(x=>x.sharedMaterial==mat&&x.sharedMaterials.Length==1);bool maps=mat.GetTexture("_BaseMap")&&mat.GetTexture("_BumpMap")&&mat.GetTexture("_MetallicGlossMap")&&mat.GetTexture("_OcclusionMap")==mat.GetTexture("_MetallicGlossMap");bool finite=rr.All(x=>x.GetComponent<MeshFilter>().sharedMesh.uv.All(u=>!float.IsNaN(u.x)&&!float.IsNaN(u.y)&&!float.IsInfinity(u.x)&&!float.IsInfinity(u.y)));Physics.SyncTransforms();File.WriteAllText(R+"/colliders_after_reload.json",JsonConvert.SerializeObject(all.SelectMany(t=>t.GetComponents<Collider>()).Select(CR).ToArray(),Formatting.Indented));var before=JArray.Parse(File.ReadAllText(R+"/colliders_before.json"));bool same=JToken.DeepEquals(before,JToken.Parse(JsonConvert.SerializeObject(all.SelectMany(t=>t.GetComponents<Collider>()).Select(CR).ToArray())));var current=JArray.Parse(File.ReadAllText(R+"/colliders_after_reload.json"));var targets=((JArray)cfg["walls"]).Select(x=>(string)x["path"]).ToArray();bool pilotSame=before.Where(x=>targets.Contains((string)x["path"])).All(x=>current.Any(y=>JToken.DeepEquals(x,y)));var unrelated=before.Where(x=>!targets.Contains((string)x["path"])&&!current.Any(y=>JToken.DeepEquals(x,y))).Select(x=>new{path=(string)x["path"],before=x,after=current.FirstOrDefault(y=>(string)y["path"]==(string)x["path"])}).ToArray();bool missing=all.Any(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0);if(!shared||!maps||!finite||!pilotSame||missing)throw new Exception("Validation failed "+JsonConvert.SerializeObject(new{shared,maps,finite,same,pilotSame,missing}));var result=new{scene=s.path,savedSceneReloaded=true,walls=rr.Length,uniqueWallMaterials=rr.Select(x=>x.sharedMaterial).Distinct().Count(),textureAssets=3,sharedPackedMask=true,finiteMetricUVs=finite,pilotWallCollidersPreserved=pilotSame,applicationColliderSnapshotPreserved=(bool)cfg["existingCollidersPreserved"],unrelatedSceneEdits=unrelated,missingScripts=missing};File.WriteAllText(R+"/verification.json",JsonConvert.SerializeObject(result,Formatting.Indented));return JsonConvert.SerializeObject(result);}}




